<?php
namespace App\Http\Controllers\Operations;
use App\Http\Controllers\Controller;use App\Models\AuditLog;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Illuminate\View\View;
class FeedStockController extends Controller{
private const UNITS=['poultry'=>'Poultry','goats'=>'Goats','rabbits'=>'Rabbits','dogs'=>'Dogs'];
public function index(Request $r):View{$u=$r->user();abort_unless($u->canAccess('feed-received')||$u->canAccess('inventory')||collect(array_keys(self::UNITS))->contains(fn($x)=>$u->canAccessFarmUnit($x)),403);$units=$u->isDataEntryOnly()?collect(self::UNITS)->only($u->assignedFarmUnits())->all():self::UNITS;$q=DB::table('feed_stock_movements')->whereIn('unit_code',array_keys($units));if($r->filled('unit'))$q->where('unit_code',$r->query('unit'));$rows=(clone $q)->latest('movement_date')->latest('id')->paginate(30)->withQueryString();$balances=(clone $q)->select('unit_code','feed_name',DB::raw("sum(case when movement_type='received' then quantity_kg else -quantity_kg end) as balance_kg"))->groupBy('unit_code','feed_name')->orderBy('unit_code')->orderBy('feed_name')->get();$canReceive=!$u->isDataEntryOnly()&&($u->canDo('feed-received','create')||$u->canDo('inventory','create')||$u->canAccess('production'));return view('operations.feed-stock.index',compact('units','rows','balances','canReceive'));}
public function store(Request $r):RedirectResponse{$u=$r->user();abort_if($u->isDataEntryOnly(),403);abort_unless($u->canDo('feed-received','create')||$u->canDo('inventory','create')||$u->canAccess('production'),403);$d=$r->validate(['unit_code'=>['required',Rule::in(array_keys(self::UNITS))],'movement_date'=>['required','date','before_or_equal:today'],'feed_name'=>['required','string','max:160'],'quantity_kg'=>['required','numeric','min:0.01'],'supplier'=>['nullable','string','max:160'],'reference'=>['nullable','string','max:100'],'unit_cost'=>['nullable','required_without:total_cost','numeric','min:0'],'total_cost'=>['nullable','required_without:unit_cost','numeric','min:0'],'notes'=>['nullable','string','max:2000']]);if(isset($d['total_cost']))$d['unit_cost']=round((float)$d['total_cost']/(float)$d['quantity_kg'],2);else$d['total_cost']=round((float)$d['quantity_kg']*(float)$d['unit_cost'],2);$id=DB::table('feed_stock_movements')->insertGetId($d+['movement_type'=>'received','recorded_by'=>$u->id,'created_at'=>now(),'updated_at'=>now()]);AuditLog::record('feed_received',null,self::UNITS[$d['unit_code']].' received '.$d['quantity_kg'].' kg of '.$d['feed_name'],null,['movement_id'=>$id], 'feed-received');return back()->with('status','Feed receipt recorded and is now visible to the assigned workers.');}}
